<script setup lang="ts">
import { ref, watch } from "vue"; import { useAppStore } from "../stores/app.js"; import { errorMessage,type ApiWorkflow } from "../types"; import type { CharacterVisualIdentityDto } from "../../../../packages/contracts/src/index.ts";
const store=useAppStore();const identity=ref<CharacterVisualIdentityDto|null>(null);const workflows=ref<ApiWorkflow[]>([]);const selectedWorkflow=ref("");const workflowJson=ref("");const validationStatus=ref("");const status=ref("准备加载设置……");
async function loadSettings(){if(!store.currentCharacterId)return;status.value="正在读取视觉档案与 Workflow……";try{identity.value=(await store.api.getCharacterVisualIdentity(store.currentCharacterId)).data}catch{identity.value=null}try{const result=await store.api.getWorkflows();workflows.value=result.data??[];const first=workflows.value[0];if(first){selectedWorkflow.value=`${first.id}@${first.version}`;workflowJson.value=JSON.stringify(first,null,2)}status.value=`${workflows.value.length} 个 Workflow 模板`;}catch(e:unknown){status.value=errorMessage(e)}}
function onWorkflowChange(){const wf=workflows.value.find(w=>`${w.id}@${w.version}`===selectedWorkflow.value);workflowJson.value=wf?JSON.stringify(wf,null,2):"";validationStatus.value=""}async function validateWorkflow(){let parsed:unknown;try{parsed=JSON.parse(workflowJson.value)}catch{validationStatus.value="Workflow JSON 格式无效。";return}try{const result=await store.api.validateWorkflow(parsed);validationStatus.value=`验证通过：${result.data.id}@${result.data.version}`}catch(e:unknown){validationStatus.value=errorMessage(e)}}watch(()=>store.currentCharacterId,()=>void loadSettings(),{immediate:true});
</script>
<template><section class="studio-page"><header class="page-header"><div><p>创作酒馆</p><h1>视觉工作台</h1><span>在这里保存角色的外观线索，也管理生成工作流。</span></div><div class="header-right"><small id="settings-status">{{status}}</small><button @click="loadSettings">刷新</button></div></header><div class="studio-grid"><aside class="identity-card"><div class="card-heading"><span>角色档案</span><i>v{{identity?.revision ?? '—'}}</i></div><div class="identity-avatar">{{store.currentCharacter?.displayName?.slice(0,1)||'?'}}</div><h2>{{store.currentCharacter?.displayName||'当前角色'}}</h2><p class="intro">{{identity?'这份档案会在生成角色视觉内容时作为基础参考。':'这个角色尚未创建视觉档案。'}}</p><template v-if="identity"><h3>视觉关键词</h3><div class="tags"><span v-for="tag in identity.styleTags" :key="tag">{{tag}}</span></div><h3>正向提示词</h3><p class="prompt">{{identity.positivePrompt}}</p><template v-if="identity.negativePrompt"><h3>避免出现</h3><p class="prompt muted">{{identity.negativePrompt}}</p></template></template></aside><main class="workflow-card"><div class="workflow-head"><div><p>生成配方</p><h2>Workflow 编辑器</h2></div><select id="workflow-select" v-model="selectedWorkflow" @change="onWorkflowChange" :disabled="!workflows.length"><option v-for="wf in workflows" :key="`${wf.id}@${wf.version}`" :value="`${wf.id}@${wf.version}`">{{wf.id}}@{{wf.version}}</option></select></div><p class="workflow-note">编辑前请确认节点字段与当前的 ComfyUI 工作流一致。</p><textarea id="workflow-json" v-model="workflowJson" rows="18" spellcheck="false" placeholder="选择一个 Workflow 模板后开始编辑…"></textarea><footer><p id="workflow-validation" :class="{success:validationStatus.includes('验证通过')} ">{{validationStatus}}</p><button id="validate-workflow" @click="validateWorkflow">检查并验证</button></footer></main></div></section></template>
<style scoped>
.studio-page{position:relative;z-index:1;height:100%;overflow:auto;padding:38px 54px;color:#4d433d}.page-header{max-width:1160px;margin:0 auto 27px;display:flex;justify-content:space-between;align-items:end}.page-header p,.workflow-head p{margin:0 0 6px;color:#b36d57;font-size:11px;font-weight:700;letter-spacing:.16em}.page-header h1{margin:0;color:#463b34;font-size:26px}.page-header>div>span{display:block;margin-top:9px;color:#a29891;font-size:13px}.header-right{display:flex;align-items:center;gap:13px}.header-right small{color:#a79b94;font-size:11px}.header-right button,.workflow-card button{border:0;border-radius:999px;padding:10px 16px;background:#b96049;color:#fff;font-size:12px;cursor:pointer}.studio-grid{max-width:1160px;margin:auto;display:grid;grid-template-columns:330px minmax(0,1fr);gap:18px}.identity-card,.workflow-card{background:#fffdfa;border:1px solid #eee2da;border-radius:18px;box-shadow:0 10px 28px rgba(119,82,60,.06)}.identity-card{padding:22px}.card-heading{display:flex;justify-content:space-between;color:#b36d57;font-size:11px;font-weight:700}.card-heading i{padding:3px 7px;border-radius:99px;background:#f9ebe4;font-style:normal}.identity-avatar{display:grid;place-items:center;width:58px;height:58px;margin:22px 0 10px;border-radius:18px;background:#f0d7cb;color:#994f3b;font-size:24px;font-weight:700}.identity-card h2{margin:0;color:#53463e;font-size:17px}.intro{margin:7px 0 22px;color:#a3968e;font-size:12px;line-height:1.7}.identity-card h3{margin:19px 0 8px;color:#86776f;font-size:10px;font-weight:700;letter-spacing:.08em}.tags{display:flex;flex-wrap:wrap;gap:6px}.tags span{padding:5px 8px;border-radius:8px;background:#fbefe9;color:#ae654e;font-size:10px}.prompt{margin:0;padding:10px;border-radius:10px;background:#fbf8f5;color:#66574f;font-family:ui-monospace,SFMono-Regular,monospace;font-size:10px;line-height:1.7;white-space:pre-wrap}.prompt.muted{color:#9e8177}.workflow-card{padding:23px}.workflow-head{display:flex;justify-content:space-between;align-items:start}.workflow-head h2{margin:0;font-size:18px;color:#51443c}.workflow-head select{max-width:270px;border:1px solid #e9ddd5;border-radius:10px;background:#fff;color:#65564e;padding:8px;font-size:11px}.workflow-note{margin:16px 0 10px;color:#a3978f;font-size:11px}.workflow-card textarea{display:block;width:100%;resize:vertical;border:1px solid #eadfd7;border-radius:13px;background:#fcfaf8;color:#64564e;padding:14px;outline:none;font-family:ui-monospace,SFMono-Regular,monospace;font-size:11px;line-height:1.6}.workflow-card textarea:focus{border-color:#d99b85}.workflow-card footer{display:flex;align-items:center;justify-content:space-between;margin-top:14px}.workflow-card footer p{margin:0;color:#bd715c;font-size:11px}.workflow-card footer p.success{color:#699681}@media(max-width:1000px){.studio-grid{grid-template-columns:1fr}.studio-page{padding:30px}}
</style>
